export function carCredits(parent){
 const details=document.createElement('details');details.className='car-credits';
 details.innerHTML='<summary>MODEL CREDITS ↗</summary><p>Detailed car models · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a></p><p>Sprint R: BMW M4 Competition M Package — <a href="https://sketchfab.com/3d-models/bmw-m4-competition-m-package-5c0a2dafb1ad408d9fc9eeef9aee531b">𝙎𝙍𝙏 𝙋𝙚𝙧𝙛𝙤𝙢𝙖𝙣𝙘𝙚™</a>.</p><p>Midnight GT: Mercedes Benz AMG GT — <a href="https://sketchfab.com/3d-models/mercedes-benz-amg-gt-661dcab94455463784651a3ebc63cfb9">Yan Carvalho</a>.</p><p>Ironclad V8: Dodge Challenger RT — <a href="https://sketchfab.com/3d-models/dodge-challenger-rt-wwwvecarzcom-73b11a33ba8c4a64a7c06ebb0fe7a93a">vecarz</a>.</p><p>Apex X: Car Concept — <a href="https://github.com/KhronosGroup/glTF-Sample-Assets/tree/main/Models/CarConcept">Eric Chadwick / Darmstadt Graphics Group GmbH, 2024</a>.</p><p>Adapted for Coastline Rush: normalized geometry, paint and finish controls, fitted stripes and wings, and simplified distant models. Car Concept license logos removed. Fictional in-game names do not imply manufacturer endorsement.</p><p>Coast Classic: ToyCar — Guido Odendahl; material extensions Eric Chadwick, via Khronos glTF Sample Assets (CC0).</p>';
 for(const a of details.querySelectorAll('a')){a.target='_blank';a.rel='noopener noreferrer';}parent.append(details);
}
